const e=[{id:"pancreas-diabetes-001",topicId:"pancreas-diabetes",question:"Как называется поджелудочная железа по-латыни?",options:["Pancreas","Hepar","Vesica fellea","Pharynx"],correctIndex:0,explanation:"Поджелудочная железа на латыни — pancreas (панкреас).",difficulty:"medium",tags:["анатомия","латынь"]},{id:"pancreas-diabetes-002",topicId:"pancreas-diabetes",question:"Какую форму имеет поджелудочная железа?",options:["Грушевидную","Продолговатую трёхгранно-призматическую","Шаровидную","Подковообразную"],correctIndex:1,explanation:"Поджелудочная железа имеет продолговатую трёхгранно-призматическую форму и серовато-розовую поверхность.",difficulty:"medium",tags:["анатомия"]},{id:"pancreas-diabetes-003",topicId:"pancreas-diabetes",question:"Какой орган превосходит поджелудочную железу по размерам среди желёз организма?",options:["Щитовидная железа","Селезёнка","Печень","Надпочечники"],correctIndex:2,explanation:"Поджелудочная железа является одной из самых крупных, уступая размерами лишь печени.",difficulty:"medium",tags:["анатомия"]},{id:"pancreas-diabetes-004",topicId:"pancreas-diabetes",question:"Каков вес поджелудочной железы?",options:["1,5–2 кг","300–400 г","10–15 г","70–80 г"],correctIndex:3,explanation:"Вес поджелудочной железы составляет 70–80 г.",difficulty:"hard",tags:["анатомия"]},{id:"pancreas-diabetes-005",topicId:"pancreas-diabetes",question:"Какова длина поджелудочной железы?",options:["16–22 см","7–10 см","2–3 см","30–40 см"],correctIndex:0,explanation:"Длина поджелудочной железы равна 16–22 см.",difficulty:"hard",tags:["анатомия"]},{id:"pancreas-diabetes-006",topicId:"pancreas-diabetes",question:"Как называется самый крупный и главный проток поджелудочной железы?",options:["Холедох","Вирсунгов проток","Пузырный проток","Печёночный проток"],correctIndex:1,explanation:"Самый крупный и главный проток поджелудочной железы — вирсунгов проток.",difficulty:"hard",tags:["анатомия","протоки"]},{id:"pancreas-diabetes-007",topicId:"pancreas-diabetes",question:"Через какие отделы железы проходит вирсунгов проток?",options:["Только через головку","Только через тело","Через хвост, тело и головку","Только через хвост"],correctIndex:2,explanation:"Вирсунгов проток тянется через хвост, тело и головку железы.",difficulty:"hard",tags:["анатомия","протоки"]},{id:"pancreas-diabetes-008",topicId:"pancreas-diabetes",question:"Как называется общий желчный проток, с которым сливается вирсунгов проток?",options:["Пузырный проток","Печёночный проток","Добавочный проток","Холедох"],correctIndex:3,explanation:"Вирсунгов проток предварительно сливается с холедохом — общим желчным протоком.",difficulty:"hard",tags:["анатомия","протоки"]},{id:"pancreas-diabetes-009",topicId:"pancreas-diabetes",question:"Как называется возвышение на двенадцатиперстной кишке, где открывается вирсунгов проток?",options:["Большой дуоденальный (фатеров) сосочек","Баугиниева заслонка","Кардия","Пилорус"],correctIndex:0,explanation:"Вирсунгов проток открывается на большом дуоденальном, или фатеровом, сосочке двенадцатиперстной кишки.",difficulty:"hard",tags:["анатомия","протоки"]},{id:"pancreas-diabetes-010",topicId:"pancreas-diabetes",question:"Какой мышечный клапан регулирует выброс желчи и панкреатического сока в двенадцатиперстную кишку?",options:["Пилорус","Сфинктер Одди","Кардия","Баугиниева заслонка"],correctIndex:1,explanation:"Выходное отверстие на фатеровом сосочке снабжено мышечным клапаном — сфинктером Одди, регулирующим выброс желчи и панкреатического сока.",difficulty:"medium",tags:["анатомия","протоки"]},{id:"pancreas-diabetes-011",topicId:"pancreas-diabetes",question:"Сколько панкреатического сока выделяет поджелудочная железа в течение суток?",options:["100–200 мл","500–700 мл","1,5–2 л","5–6 л"],correctIndex:2,explanation:"Поджелудочная железа в течение суток выделяет 1,5–2 л сока.",difficulty:"hard",tags:["физиология"]},{id:"pancreas-diabetes-012",topicId:"pancreas-diabetes",question:"Для чего в панкреатическом соке содержатся бикарбонаты?",options:["Для расщепления белков","Для всасывания витаминов","Для эмульгирования жиров","Для ощелачивания кислого содержимого двенадцатиперстной кишки"],correctIndex:3,explanation:"Бикарбонаты панкреатического сока нужны для ощелачивания кислого содержимого 12-перстной кишки, поступившего из желудка.",difficulty:"hard",tags:["физиология"]},{id:"pancreas-diabetes-013",topicId:"pancreas-diabetes",question:"Какие ферменты являются основными компонентами панкреатического сока?",options:["Трипсин, химотрипсин, амилаза, липаза и нуклеаза","Пепсин и соляная кислота","Инсулин и глюкагон","Желчные кислоты и билирубин"],correctIndex:0,explanation:"Основными компонентами панкреатического сока являются ферменты трипсин и химотрипсин, амилаза, липаза, нуклеаза и многие другие.",difficulty:"medium",tags:["физиология","ферменты"]},{id:"pancreas-diabetes-014",topicId:"pancreas-diabetes",question:"Как называется процесс расщепления белков ферментами?",options:["Липолиз","Протеолиз","Гликолиз","Гидролиз воды"],correctIndex:1,explanation:"Ферменты панкреатического сока осуществляют расщепление белков — протеолиз.",difficulty:"medium",tags:["физиология","терминология"]},{id:"pancreas-diabetes-015",topicId:"pancreas-diabetes",question:"Каким термином обозначается расщепление жиров?",options:["Протеолиз","Гликолиз","Липолиз","Глюконеогенез"],correctIndex:2,explanation:"Расщепление жиров называется липолизом.",difficulty:"medium",tags:["физиология","терминология"]},{id:"pancreas-diabetes-016",topicId:"pancreas-diabetes",question:"Как называется расщепление сахаров?",options:["Липолиз","Протеолиз","Гемолиз","Гликолиз"],correctIndex:3,explanation:"Расщепление сахаров называется гликолизом.",difficulty:"medium",tags:["физиология","терминология"]},{id:"pancreas-diabetes-017",topicId:"pancreas-diabetes",question:"Как называется воспаление поджелудочной железы?",options:["Панкреатит","Холецистит","Гепатит","Гастрит"],correctIndex:0,explanation:"Воспаление поджелудочной железы называется панкреатитом.",difficulty:"easy",tags:["терминология"]},{id:"pancreas-diabetes-018",topicId:"pancreas-diabetes",question:"В чём заключается экзокринная функция поджелудочной железы?",options:["В выработке гормонов, поступающих в кровь","В выделении панкреатического сока с ферментами в двенадцатиперстную кишку","В накоплении гликогена","В обезвреживании токсинов"],correctIndex:1,explanation:"Экзокринная функция — выделение панкреатического сока с ферментами, который поступает в двенадцатиперстную кишку и помогает переваривать пищу.",difficulty:"medium",tags:["физиология","функции"]},{id:"pancreas-diabetes-019",topicId:"pancreas-diabetes",question:"Какие гормоны вырабатывает поджелудочная железа в рамках эндокринной функции?",options:["Кортизон и гидрокортизон","Адреналин и норадреналин","Инсулин и глюкагон","Ренин и альдостерон"],correctIndex:2,explanation:"Эндокринная (гормональная) функция — выработка инсулина и глюкагона, регулирующих уровень глюкозы в крови.",difficulty:"medium",tags:["физиология","функции"]},{id:"pancreas-diabetes-020",topicId:"pancreas-diabetes",question:"Как действуют инсулин и глюкагон на уровень сахара в крови?",options:["Оба снижают сахар","Оба повышают сахар","Оба не влияют на уровень сахара","Инсулин снижает сахар, а глюкагон повышает его"],correctIndex:3,explanation:"Инсулин снижает сахар, а глюкагон повышает его.",difficulty:"medium",tags:["физиология","гормоны"]},{id:"pancreas-diabetes-021",topicId:"pancreas-diabetes",question:"Что лежит в основе сахарного диабета?",options:["Дефицит образования собственного инсулина или нечувствительность клеток к инсулину и повышение глюкозы крови","Избыточная выработка инсулина","Нарушение выработки пищеварительных ферментов","Воспаление протоков поджелудочной железы"],correctIndex:0,explanation:"Сахарный диабет — хроническое нарушение обмена веществ, в основе которого лежит дефицит образования собственного инсулина или нечувствительность клеток к инсулину и повышение уровня глюкозы в крови.",difficulty:"medium",tags:["диабет","определение"]},{id:"pancreas-diabetes-022",topicId:"pancreas-diabetes",question:"Какими клетками вырабатывается инсулин?",options:["Ацинусами поджелудочной железы","β-клетками островков Лангерганса","Гепатоцитами печени","Клетками слизистой двенадцатиперстной кишки"],correctIndex:1,explanation:"Выработка инсулина происходит в поджелудочной железе β-клетками островков Лангерганса.",difficulty:"medium",tags:["диабет","физиология"]},{id:"pancreas-diabetes-023",topicId:"pancreas-diabetes",question:"Чем характеризуется сахарный диабет 1 типа?",options:["Клетки теряют чувствительность к инсулину","Возникает впервые во время беременности","Поджелудочная железа практически не вырабатывает инсулин","Уровень глюкозы остаётся нормальным"],correctIndex:2,explanation:"При диабете 1 типа (инсулинозависимом) поджелудочная железа практически не вырабатывает инсулин.",difficulty:"medium",tags:["диабет","классификация"]},{id:"pancreas-diabetes-024",topicId:"pancreas-diabetes",question:"В каком возрасте обычно развивается сахарный диабет 1 типа?",options:["После 60 лет","После 40 лет","Только у новорождённых","В молодом возрасте"],correctIndex:3,explanation:"Диабет 1 типа обычно развивается в молодом возрасте и требует постоянных инъекций инсулина.",difficulty:"medium",tags:["диабет","классификация"]},{id:"pancreas-diabetes-025",topicId:"pancreas-diabetes",question:"Что происходит с клетками организма при сахарном диабете 2 типа?",options:["Они теряют чувствительность к инсулину","Они перестают вырабатывать глюкагон","Они разрушаются иммунной системой","Они начинают вырабатывать инсулин самостоятельно"],correctIndex:0,explanation:"При диабете 2 типа (инсулиннезависимом) клетки организма теряют чувствительность к инсулину.",difficulty:"medium",tags:["диабет","классификация"]},{id:"pancreas-diabetes-026",topicId:"pancreas-diabetes",question:"С чем связан сахарный диабет 2 типа?",options:["С аутоиммунным разрушением железы","С ожирением и малоактивным образом жизни","С наследственным дефектом ферментов","С перенесённой вирусной инфекцией в детстве"],correctIndex:1,explanation:"Диабет 2 типа чаще встречается у людей старше 30–40 лет и связан с ожирением и малоактивным образом жизни.",difficulty:"medium",tags:["диабет","этиология"]},{id:"pancreas-diabetes-027",topicId:"pancreas-diabetes",question:"Когда возникает гестационный диабет?",options:["В детском возрасте","В период менопаузы","Впервые во время беременности","После хирургических вмешательств"],correctIndex:2,explanation:"Гестационный диабет возникает впервые во время беременности.",difficulty:"medium",tags:["диабет","классификация"]},{id:"pancreas-diabetes-028",topicId:"pancreas-diabetes",question:"Какие ранние симптомы характерны для сахарного диабета?",options:["Отёки ног и одышка","Кашель и боль в грудной клетке","Желтуха и горечь во рту","Постоянная жажда, сухость во рту и учащённое мочеиспускание"],correctIndex:3,explanation:"Ранние симптомы диабета: постоянная жажда и сухость во рту, учащённое мочеиспускание особенно ночью, утомляемость и мышечная слабость.",difficulty:"medium",tags:["диабет","симптомы"]},{id:"pancreas-diabetes-029",topicId:"pancreas-diabetes",question:"Как изменяется вес при сахарном диабете разных типов?",options:["Похудение при 1 типе, прибавка при 2 типе","Прибавка при 1 типе, похудение при 2 типе","Вес не изменяется ни при одном типе","Похудение при обоих типах"],correctIndex:0,explanation:"Отмечаются резкие изменения веса: похудение при 1 типе, прибавка при 2 типе.",difficulty:"hard",tags:["диабет","симптомы"]},{id:"pancreas-diabetes-030",topicId:"pancreas-diabetes",question:"Какие изменения со стороны кожи характерны для сахарного диабета?",options:["Желтушность и сосудистые звёздочки","Долгое заживление ран и кожный зуд","Только повышенная потливость","Только бледность и мраморность"],correctIndex:1,explanation:"К ранним признакам диабета относятся долгое заживление ран и кожный зуд.",difficulty:"medium",tags:["диабет","симптомы"]},{id:"pancreas-diabetes-031",topicId:"pancreas-diabetes",question:"Какое поражение глаз развивается при неконтролируемом высоком сахаре?",options:["Катаракта врождённая","Глаукома","Ретинопатия со снижением зрения","Конъюнктивит"],correctIndex:2,explanation:"Без контроля высокий сахар ведёт к снижению зрения — ретинопатии.",difficulty:"medium",tags:["диабет","осложнения"]},{id:"pancreas-diabetes-032",topicId:"pancreas-diabetes",question:"Как называется осложнение диабета, приводящее к гангрене конечностей?",options:["Диабетическая ретинопатия","Диабетическая нефропатия","Диабетическая энцефалопатия","Диабетическая стопа"],correctIndex:3,explanation:"Диабетическая стопа — осложнение, ведущее к гангрене конечностей.",difficulty:"medium",tags:["диабет","осложнения"]},{id:"pancreas-diabetes-033",topicId:"pancreas-diabetes",question:"Какие сердечно-сосудистые последствия вызывает неконтролируемый высокий сахар?",options:["Поражение сосудов с развитием инфаркта и инсульта","Только снижение артериального давления","Только замедление сердечного ритма","Только варикозное расширение вен"],correctIndex:0,explanation:"Без контроля высокий сахар ведёт к поражению сосудов — инфаркту и инсульту.",difficulty:"medium",tags:["диабет","осложнения"]},{id:"pancreas-diabetes-034",topicId:"pancreas-diabetes",question:"Каким прибором измеряется сахар крови?",options:["Тонометром","Глюкометром","Спирометром","Пульсоксиметром"],correctIndex:1,explanation:"Сахар крови измеряется глюкометром.",difficulty:"easy",tags:["диабет","диагностика"]},{id:"pancreas-diabetes-035",topicId:"pancreas-diabetes",question:"Каков нормальный уровень глюкозы натощак у здорового взрослого человека?",options:["От 1,5 до 3,0 ммоль/л","От 5,6 до 6,9 ммоль/л","От 3,3 до 5,5 ммоль/л","От 7,0 до 11,0 ммоль/л"],correctIndex:2,explanation:"У здорового взрослого человека уровень глюкозы натощак составляет от 3,3 до 5,5 ммоль/л.",difficulty:"medium",tags:["диабет","нормы"]},{id:"pancreas-diabetes-036",topicId:"pancreas-diabetes",question:"Какой диапазон глюкозы натощак расценивается как предиабетическое состояние?",options:["3,3–5,5 ммоль/л","7,0–8,0 ммоль/л","Ниже 3,0 ммоль/л","5,6–6,9 ммоль/л"],correctIndex:3,explanation:"Повышение глюкозы до 5,6–6,9 ммоль/л расценивается как нарушение гликемии натощак и относится к предиабетическим состояниям.",difficulty:"hard",tags:["диабет","нормы"]},{id:"pancreas-diabetes-037",topicId:"pancreas-diabetes",question:"Какое значение глюкозы венозной плазмы при повторном измерении является диагностическим критерием сахарного диабета?",options:["7,0 ммоль/л и выше","5,5 ммоль/л и выше","6,0 ммоль/л и выше","11,1 ммоль/л и выше"],correctIndex:0,explanation:"Значение глюкозы венозной плазмы 7,0 ммоль/л и выше при повторном измерении является диагностическим критерием сахарного диабета.",difficulty:"hard",tags:["диабет","нормы"]},{id:"pancreas-diabetes-038",topicId:"pancreas-diabetes",question:"Какого уровня не превышает глюкоза у здорового человека через два часа после еды?",options:["5,5 ммоль/л","7,8 ммоль/л","11,0 ммоль/л","3,3 ммоль/л"],correctIndex:1,explanation:"У здорового человека через два часа после еды уровень глюкозы не превышает 7,8 ммоль/л.",difficulty:"hard",tags:["диабет","нормы"]},{id:"pancreas-diabetes-039",topicId:"pancreas-diabetes",question:"О чём свидетельствуют значения глюкозы от 7,8 до 11,0 ммоль/л через два часа после еды?",options:["О норме","О гипогликемии","О нарушенной толерантности к глюкозе","О подтверждённом диабете"],correctIndex:2,explanation:"Значения от 7,8 до 11,0 ммоль/л свидетельствуют о нарушенной толерантности к глюкозе.",difficulty:"hard",tags:["диабет","нормы"]},{id:"pancreas-diabetes-040",topicId:"pancreas-diabetes",question:"Какой уровень глюкозы через два часа после еды указывает на сахарный диабет?",options:["5,5 ммоль/л и выше","6,9 ммоль/л и выше","7,8 ммоль/л и выше","11,1 ммоль/л и выше"],correctIndex:3,explanation:"Уровень 11,1 ммоль/л и выше через два часа после еды указывает на сахарный диабет.",difficulty:"hard",tags:["диабет","нормы"]},{id:"pancreas-diabetes-041",topicId:"pancreas-diabetes",question:"Что отражает показатель гликированного гемоглобина HbA1c?",options:["Средний уровень глюкозы крови за предшествующие 2–3 месяца","Уровень глюкозы в момент забора крови","Количество инсулина в крови","Скорость всасывания углеводов"],correctIndex:0,explanation:"HbA1c отражает средний уровень глюкозы крови за предшествующие 2–3 месяца.",difficulty:"medium",tags:["диабет","диагностика"]},{id:"pancreas-diabetes-042",topicId:"pancreas-diabetes",question:"Каково нормальное значение гликированного гемоглобина?",options:["От 5,7 % до 6,4 %","Менее 5,7 %","6,5 % и выше","От 7 % до 8 %"],correctIndex:1,explanation:"В норме HbA1c составляет менее 5,7 %.",difficulty:"hard",tags:["диабет","нормы"]},{id:"pancreas-diabetes-043",topicId:"pancreas-diabetes",question:"Какие значения HbA1c соответствуют предиабету?",options:["Менее 5,7 %","6,5 % и выше","От 5,7 % до 6,4 %","От 8 % до 10 %"],correctIndex:2,explanation:"Показатели HbA1c от 5,7 % до 6,4 % соответствуют предиабету.",difficulty:"hard",tags:["диабет","нормы"]},{id:"pancreas-diabetes-044",topicId:"pancreas-diabetes",question:"Какой уровень HbA1c является диагностическим критерием сахарного диабета?",options:["Менее 5,7 %","5,7 % и выше","6,0 % и выше","6,5 % и выше"],correctIndex:3,explanation:"Уровень HbA1c 6,5 % и выше является диагностическим критерием сахарного диабета.",difficulty:"hard",tags:["диабет","нормы"]},{id:"pancreas-diabetes-045",topicId:"pancreas-diabetes",question:"При каких состояниях снижается достоверность показателя HbA1c?",options:["При анемиях, гемоглобинопатиях и повышенном разрушении эритроцитов","При заболеваниях щитовидной железы","При приёме антибиотиков","При физических нагрузках"],correctIndex:0,explanation:"Достоверность HbA1c снижается при анемиях, гемоглобинопатиях и состояниях с повышенным разрушением эритроцитов.",difficulty:"hard",tags:["диабет","диагностика"]},{id:"pancreas-diabetes-046",topicId:"pancreas-diabetes",question:"При каком уровне глюкозы, как правило, развивается гипогликемическая кома?",options:["Ниже 5,5 ммоль/л","Ниже 3,0 ммоль/л","Выше 11,1 ммоль/л","Ниже 7,0 ммоль/л"],correctIndex:1,explanation:"Гипогликемическая кома развивается при резком снижении уровня глюкозы крови, как правило ниже 3,0 ммоль/л.",difficulty:"hard",tags:["диабет","неотложные состояния"]},{id:"pancreas-diabetes-047",topicId:"pancreas-diabetes",question:"К чему приводит резкое снижение глюкозы крови при гипогликемической коме?",options:["К накоплению кетоновых тел","К метаболическому ацидозу","К энергетическому голоданию головного мозга","К обезвоживанию организма"],correctIndex:2,explanation:"Резкое снижение глюкозы приводит к энергетическому голоданию головного мозга.",difficulty:"medium",tags:["диабет","неотложные состояния"]},{id:"pancreas-diabetes-048",topicId:"pancreas-diabetes",question:"Какие причины вызывают гипогликемическую кому?",options:["Пропуск или отмена инсулина","Инфекции и стрессовые состояния","Поздняя диагностика сахарного диабета","Передозировка инсулина, пропуск приёма пищи, интенсивная нагрузка без углеводов, алкоголь"],correctIndex:3,explanation:"Причинами гипогликемической комы являются передозировка инсулина или пероральных сахароснижающих препаратов, пропуск приёма пищи, интенсивная физическая нагрузка без дополнительного приёма углеводов, употребление алкоголя, а также заболевания печени и почек.",difficulty:"hard",tags:["диабет","неотложные состояния"]},{id:"pancreas-diabetes-049",topicId:"pancreas-diabetes",question:"Какие ранние проявления характерны для гипогликемической комы?",options:["Резкая слабость, чувство сильного голода, тремор рук, потливость, тахикардия, тревожность","Запах ацетона изо рта и шумное дыхание","Желтуха и кожный зуд","Отёки и асцит"],correctIndex:0,explanation:"Клиническая картина гипогликемии: резкая слабость, чувство сильного голода, тремор рук, потливость, тахикардия, тревожность.",difficulty:"medium",tags:["диабет","неотложные состояния"]},{id:"pancreas-diabetes-050",topicId:"pancreas-diabetes",question:"Какие симптомы присоединяются при дальнейшем снижении уровня глюкозы?",options:["Только усиление голода","Головокружение, нарушение зрения и речи, дезориентация, судороги и потеря сознания","Только потливость и тремор","Обильное мочеиспускание и жажда"],correctIndex:1,explanation:"По мере снижения уровня глюкозы присоединяются нейрогликопенические симптомы: головокружение, нарушение зрения и речи, дезориентация, судороги и потеря сознания с развитием комы.",difficulty:"hard",tags:["диабет","неотложные состояния"]},{id:"pancreas-diabetes-051",topicId:"pancreas-diabetes",question:"При каком типе сахарного диабета чаще возникает гипергликемическая кома?",options:["Только при гестационном","Только при 2 типе","При 1 типе, но может развиваться и при 2 типе","Она не связана с типом диабета"],correctIndex:2,explanation:"Гипергликемическая кома чаще возникает при сахарном диабете 1 типа, но может развиваться и при 2 типе.",difficulty:"medium",tags:["диабет","неотложные состояния"]},{id:"pancreas-diabetes-052",topicId:"pancreas-diabetes",question:"Что может спровоцировать развитие гипергликемической комы?",options:["Передозировка инсулина и пропуск еды","Употребление большого количества воды","Интенсивная физическая нагрузка","Пропуск или отмена инсулина, инфекции, стресс, травмы, операции, поздняя диагностика диабета"],correctIndex:3,explanation:"Причинами гипергликемической комы являются пропуск или отмена инсулина, инфекции, стрессовые состояния, травмы, хирургические вмешательства, а также поздняя диагностика сахарного диабета.",difficulty:"medium",tags:["диабет","неотложные состояния"]},{id:"pancreas-diabetes-053",topicId:"pancreas-diabetes",question:"Что лежит в основе патогенеза кетоацидотической комы?",options:["Абсолютная недостаточность инсулина","Избыток инсулина в крови","Дефицит глюкагона","Нарушение всасывания углеводов"],correctIndex:0,explanation:"В основе патогенеза кетоацидотической комы лежит абсолютная недостаточность инсулина.",difficulty:"hard",tags:["диабет","неотложные состояния"]},{id:"pancreas-diabetes-054",topicId:"pancreas-diabetes",question:"К чему приводит накопление кетоновых тел при кетоацидотической коме?",options:["К метаболическому алкалозу","К метаболическому ацидозу и тяжёлой интоксикации организма","К повышению артериального давления","К гипогликемии"],correctIndex:1,explanation:"Накопление кетоновых тел вызывает метаболический ацидоз и тяжёлую интоксикацию организма.",difficulty:"hard",tags:["диабет","неотложные состояния"]},{id:"pancreas-diabetes-055",topicId:"pancreas-diabetes",question:"Какой характерный признак изо рта отмечается при кетоацидотической коме?",options:["Запах ментола","Гнилостный запах","Запах ацетона","Запах аммиака"],correctIndex:2,explanation:"Характерным признаком кетоацидотической комы является запах ацетона изо рта.",difficulty:"medium",tags:["диабет","неотложные состояния"]},{id:"pancreas-diabetes-056",topicId:"pancreas-diabetes",question:"Каким становится дыхание при прогрессировании кетоацидотической комы?",options:["Поверхностным и редким","Свистящим с затруднённым выдохом","Полностью не изменяется","Глубоким и шумным"],correctIndex:3,explanation:"При кетоацидотической коме дыхание становится глубоким и шумным.",difficulty:"hard",tags:["диабет","неотложные состояния"]},{id:"pancreas-diabetes-057",topicId:"pancreas-diabetes",question:"Как развивается клиническая картина кетоацидотической комы?",options:["Постепенно","Мгновенно, в течение секунд","Всегда бессимптомно","Только после физической нагрузки"],correctIndex:0,explanation:"Клиническая картина кетоацидотической комы развивается постепенно.",difficulty:"medium",tags:["диабет","неотложные состояния"]},{id:"pancreas-diabetes-058",topicId:"pancreas-diabetes",question:"Какое действующее вещество относится к антигипергликемическим препаратам?",options:["Панкреатин","Метформин","Омепразол","Урсодезоксихолевая кислота"],correctIndex:1,explanation:"Метформин относится к антигипергликемическим препаратам наряду с гликлазидом, глибенкламидом, глимепиридом, вилдаглиптином и ситаглиптином.",difficulty:"medium",tags:["диабет","препараты"]},{id:"pancreas-diabetes-059",topicId:"pancreas-diabetes",question:"Укажите антигипергликемическое средство среди приведённых наименований.",options:["Лоперамид","Адеметионин","Гликлазид","Ондансетрон"],correctIndex:2,explanation:"Гликлазид входит в таблицу антигипергликемических препаратов.",difficulty:"medium",tags:["диабет","препараты"]},{id:"pancreas-diabetes-060",topicId:"pancreas-diabetes",question:"С каким действующим веществом чаще всего комбинируются другие антигипергликемические препараты?",options:["С гликлазидом","С глимепиридом","С ситаглиптином","С метформином"],correctIndex:3,explanation:"В таблице приведены комбинации глибенкламида, вилдаглиптина и ситаглиптина с метформином.",difficulty:"hard",tags:["диабет","препараты"]},{id:"pancreas-diabetes-061",topicId:"pancreas-diabetes",question:"Какие два действующих вещества из антигипергликемических препаратов относятся к глиптинам?",options:["Вилдаглиптин и ситаглиптин","Гликлазид и глимепирид","Метформин и глибенкламид","Глимепирид и вилдаглиптин"],correctIndex:0,explanation:"В таблице антигипергликемических препаратов приведены вилдаглиптин и ситаглиптин.",difficulty:"hard",tags:["диабет","препараты"]},{id:"pancreas-diabetes-062",topicId:"pancreas-diabetes",question:"В каких формах выпуска применяются инсулины?",options:["Только в таблетках","Во флаконах и в форме готового шприца","Только в виде ингаляций","Только в виде мази"],correctIndex:1,explanation:"Инсулины применяются во флаконах и в форме готового шприца.",difficulty:"medium",tags:["диабет","инсулин"]},{id:"pancreas-diabetes-063",topicId:"pancreas-diabetes",question:"Какое лечение требуется пациентам с сахарным диабетом 1 типа?",options:["Только диета","Только физические упражнения","Постоянные инъекции инсулина","Только приём таблетированных препаратов"],correctIndex:2,explanation:"Диабет 1 типа (инсулинозависимый) требует постоянных инъекций инсулина.",difficulty:"medium",tags:["диабет","лечение"]},{id:"pancreas-diabetes-064",topicId:"pancreas-diabetes",question:"Какое поражение почек развивается при неконтролируемом сахарном диабете?",options:["Пиелонефрит","Мочекаменная болезнь","Гломерулонефрит аутоиммунный","Почечная недостаточность"],correctIndex:3,explanation:"Среди последствий неконтролируемого высокого сахара указана почечная недостаточность.",difficulty:"medium",tags:["диабет","осложнения"]}];export{e as default};
